/* AC81: mockup v2's tokens (desk-v2.html:18-66), light, then dark: following the phone's setting
   (prefers-color-scheme), with no switch on the desk (C, stage 7's AC88). Vermilion (--you) only for
   what needs the owner; --ok, --bad and --gold for pass, fail and next to reach; the four phase
   colours, each always with its phase's name; --ink2 the agents' grey. */
html.sb .v2, html.sb.v2-page {
  --bg: #ffffff; --bg2: #f7f7f8; --card: #fbfbfb; --chip: #f1f1f3; --line: #e7e7ea; --line2: #d6d6db;
  --ink: #18191c; --ink2: #5c5f66; --ink3: #6a6d75;
  --you: #c9380c; --on-you: #ffffff; --ok: #12733a; --bad: #b3162a; --gold: #8a6a10;
  --ph-disc: #0f766e; --ph-des: #9d2f7e; --ph-build: #5c6a10; --ph-launch: #7a5a48;
  --shadow: 0 8px 28px rgb(24 25 28 / .12), 0 1px 3px rgb(24 25 28 / .08); --scrim: rgb(24 25 28 / .32);
  --font: "IBM Plex Sans", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, monospace;
  --t-title: 600 24px/1.2 var(--font);
  --t-sheet: 600 18px/1.3 var(--font);
  --t-lead: 400 15px/1.45 var(--font);
  --t-row: 500 13px/1.35 var(--font);
  --t-body: 400 13px/1.45 var(--font);
  --t-small: 400 12px/1.4 var(--font);
  --t-label: 500 11px/1.35 var(--font);
  --t-mono: 400 11px/1.4 var(--mono);
  --t-input: 400 16px/1.4 var(--font);
  --focus: var(--ink);
  color-scheme: light;
}
@media (prefers-color-scheme: dark) {
  html.sb:not([data-theme="light"]) .v2, html.sb.v2-page:not([data-theme="light"]) {
    --bg: #0f1012; --bg2: #141517; --card: #17181b; --chip: #212226; --line: #26282c; --line2: #34363c;
    --ink: #ecedef; --ink2: #a2a5ac; --ink3: #9a9da5;
    --you: #ff6a3d; --on-you: #0f1012; --ok: #4cc06a; --bad: #ff6b78; --gold: #c9b04f;
    --ph-disc: #65bdb3; --ph-des: #f07cca; --ph-build: #a4b562; --ph-launch: #c6a28f;
    --shadow: 0 8px 28px rgb(0 0 0 / .55), 0 0 0 1px rgb(255 255 255 / .05); --scrim: rgb(0 0 0 / .58);
    color-scheme: dark;
  }
}
html.sb[data-theme="dark"] .v2, html.sb.v2-page[data-theme="dark"] {
  --bg: #0f1012; --bg2: #141517; --card: #17181b; --chip: #212226; --line: #26282c; --line2: #34363c;
  --ink: #ecedef; --ink2: #a2a5ac; --ink3: #9a9da5;
  --you: #ff6a3d; --on-you: #0f1012; --ok: #4cc06a; --bad: #ff6b78; --gold: #c9b04f;
  --ph-disc: #65bdb3; --ph-des: #f07cca; --ph-build: #a4b562; --ph-launch: #c6a28f;
  --shadow: 0 8px 28px rgb(0 0 0 / .55), 0 0 0 1px rgb(255 255 255 / .05); --scrim: rgb(0 0 0 / .58);
  color-scheme: dark;
}
html.sb.v2-page, html.sb.v2-page body { background: var(--bg); color: var(--ink); }
/* From stage 7 (AC88): every trial-view screen is on mockup v2's ground (sandbox.js sets html.v2-page on each),
   and the screens no frame redraws (the Team screen and its members' pages, the Chief of Staff's page,
   "Details"' views, the bubbles and the sheets) keep their layout and their words: only their fonts and colours
   move onto AC81's tokens. Their rules, above this block, name the shared look's tokens; on mockup v2's ground
   each of those names resolves to one of AC81's, in light and in dark (the value it names is the theme's), so no
   screen mixes the old look with the new. The grounds and inks take mockup v2's; pass and fail take --ok and
   --bad; the agents' blue and the merge purple, which mockup v2 does not use (it marks agents and merges by icon
   and word), the agents' grey --ink2; the blocker amber, which marked a read that failed, --bad, as Home's and
   Waiting's "Can't read" lines have it; the runs' shades mockup v2's greys; the running log's four lanes, in turn,
   --ink, --ink2, --ink3 and --ink, each with its own line, solid, dashed, dotted and dashed (the owner's ruling,
   P-001-desk-v2-lanes.md, A; the lines are AC49's rules above), vermilion being only for what needs the owner
   (AC81); and the seven type roles
   the nearest of mockup v2's (AC81: "Text no frame draws ... takes the nearest role"): a screen's title
   --t-title, a section head --t-label, an item's title --t-row, sentences --t-body, secondary lines --t-small,
   quoted record text --t-body (AC81: "body with a left rule"), and codes --t-mono. */
html.sb.v2-page {
  --page: var(--bg); --surf: var(--card); --surf2: var(--bg2); --muted: var(--ink2); --soft: var(--ink3); --tie: var(--line2); --idle: var(--line2);
  --yous: var(--chip); --agent: var(--ink2); --agents: var(--chip); --merge: var(--ink2); --merges: var(--chip);
  --pass: var(--ok); --passs: var(--chip); --passl: var(--line2); --fail: var(--bad); --fails: var(--chip); --block: var(--bad); --blocks: var(--bg2);
  --golds: var(--bg2); --on: var(--bg);
  --run1: var(--ink2); --run2: var(--ink2); --run3: var(--ink2); --run4: var(--ink2);
  --shade0: var(--ink); --shade1: var(--ink2); --shade2: var(--ink3); --shade3: var(--ink);
  --you0: var(--ink); --you1: var(--ink2); --you2: var(--ink3); --you3: var(--ink);
  --t-screen: var(--t-title); --t-section: var(--t-label); --t-item: var(--t-row); --t-meta: var(--t-small); --t-quote: var(--t-body); --t-code: var(--t-mono);
  --track: 0;
}
/* The sheets no frame redraws (AC88: the Team's "Working now" and "Summary"): a sheet's title takes --t-sheet, as
   mockup v2's sheets have theirs (AC81, "--t-sheet ... a sheet's title"), and the sheet mockup v2's shadow. */
html.sb.v2-page .sb-sheet-t { font: var(--t-sheet); }
html.sb.v2-page .sb-sheet { box-shadow: var(--shadow); }
html.sb body { padding-bottom: calc(96px + env(safe-area-inset-bottom, 0px)); /* AC81: every screen keeps room for the bar at its foot, with the safe areas */ }
/* Stage 8 (the Design reviewer's round 1, part B item 26; frames H1, 1, 5 and 11): every screen starts 14 px down, as
   mockup v2's screen does (`.scr`, desk-v2.html:97), Team's and each detail screen's too; the Timeline's pinned head sits
   flush at the top with its own 8 px inside, as frame 7b's `.thead` does (desk-v2.html:278). */
html.sb.v2-page main#view > .sb-screen { padding-top: 14px; }
html.sb.v2-page main#view > .v2-timeline > .v2-tlhead { margin-top: -14px; }
.v2 { font: var(--t-body); color: var(--ink); }
.v2 :focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; }
/* The resets carry no weight (:where), so every v2 class below outranks them (stage 1a's build review,
   round 1, the design reviewer's F1: a `.v2 button` reset had out-ranked the board's button classes). */
:where(.v2) :where(p, h1, h2, h3, ol, ul) { margin: 0; }
:where(.v2) :where(ol, ul) { list-style: none; padding: 0; }
:where(.v2) a { color: inherit; text-decoration: none; }
:where(.v2) :where(b, strong) { font-weight: 600; }
:where(.v2) button { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; text-align: left; }
.v2-k { width: 14px; height: 14px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.v2-i { width: 20px; height: 20px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
.v2-k .fill, .v2-i .fill { fill: currentColor; stroke: none; }
.v2-mono { font: var(--t-mono); color: var(--ink2); }
.v2-small { font: var(--t-small); color: var(--ink2); }
.v2-body { font: var(--t-body); }
.v2-label { font: var(--t-label); color: var(--ink2); }
.v2-lnk { font: 500 12px/1.4 var(--font); color: var(--ink); text-decoration: underline; text-underline-offset: 2px; min-height: 28px; display: inline-flex; align-items: center; }

