// ac-test: S-001/AC98 — the headers sized as headers (stage HD1; the approved header picture, docs/design/builds/headers-picture/,
// images 1 to 8, with the owner's answers "Bigger titles too", B, "All dark", A, and "Keep that part small", A). The suite has no
// browser (AC80's method), so the page is the sandbox's own code under the fake DOM, and the stylesheets the page loads
// (style.css, then sandbox.css) are cascaded over what it drew (tests/desk/css-cascade.mjs): every screen and sheet from each
// fixture — AC62's and AC81's (screen-text.mjs: Service-Desk at 3117150 from `service-desk/`, a made-up project with one item of
// each kind, and a v2.5 project in `poom/`'s placeholder form), `md-extremes/` (sandbox-fixtures.mjs's five made-up projects),
// Service-Desk with J12's built pull requests, and Plan's made-up estimates (wa-fixtures.mjs) — and the states the walk does not
// reach on its own (glance-fixtures.mjs, qw1-fixtures.mjs and vt1-fixtures.mjs: Home with "Since you last looked", Waiting with
// questions and with none, the Kicked back strip with cards, an opened phase with two runs, the value targets' sheet; all made
// up, NOT real records), in dark (forced, and the phone's own) and light, at 360 and 414 px. Each role in AC98's table is
// checked by selector: its computed size, weight and colour; the kept-small roles, each measured, unchanged; the tokens'
// values unchanged; and the two headings' small part. The stage-8 guard's exception for HD1 is AC88's test's
// (tests/desk/ac88-dark.test.mjs, `HD1_ONCE`); the Chromium captures at 360 × 740 and 414 × 896 are the pull request's.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { SRC, CONFIG } from './helpers.mjs';
import { loadSandbox, findAll, byClass, openIdle } from './sandbox-helpers.mjs';
import { NOW, extremes } from './sandbox-fixtures.mjs';
import { textSetup } from './screen-text.mjs';
import { SD3, sdRepo } from './tv2-fixtures.mjs';
import { waSetup, WORKED, memStore } from './wa-fixtures.mjs';
import { parseCss, treeOf, cascade, nodes } from './css-cascade.mjs';
import { PF_ROWS } from '../../src/public/lib/portfolio.js';
import { HOME_WORDS } from '../../src/lib/home.js';
import { PAGE_WORDS } from '../../src/lib/projectpage.js';
import { quietState, twoMixState, textState, gatesState, deviceMarks, KICKED, GATE4, GATE_KEY, MIX_PROJECT, SD, G9_OPENS, lookedAt } from './glance-fixtures.mjs';
import { QW1_OPENS } from './qw1-fixtures.mjs';
import { VT1_OPENS } from './vt1-fixtures.mjs';
import { POLL_MS } from '../../src/lib/scheduler.js';

const SANDBOX_CSS = readFileSync(join(SRC, 'public', 'sandbox.css'), 'utf8');
const JS = readFileSync(join(SRC, 'public', 'sandbox.js'), 'utf8');
const RULES = (() => {
  const a = parseCss(readFileSync(join(SRC, 'public', 'style.css'), 'utf8'), 'style.css');
  const b = parseCss(SANDBOX_CSS, 'sandbox.css').map((r) => ({ ...r, order: r.order + a.length }));
  return [...a, ...b];
})();
const FLAT = SANDBOX_CSS.replace(/\/\*[\s\S]*?\*\//g, '');
const V2 = FLAT.slice(FLAT.indexOf('@font-face')); // mockup v2's block (AC62's and AC81's tests)
const OLDER = FLAT.slice(0, FLAT.indexOf('@font-face'));
const rule = (sel) => {
  const re = new RegExp(`(?:^|})\\s*${sel.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*\\{([^}]*)\\}`);
  const m = re.exec(V2);
  return m ? m[1] : '';
};

const INK = { light: { ink: '#18191c', ink2: '#5c5f66' }, dark: { ink: '#ecedef', ink2: '#a2a5ac' } };
const GROUND = { light: ['#ffffff', '#f7f7f8', '#fbfbfb', '#f1f1f3'], dark: ['#0f1012', '#141517', '#17181b', '#212226'] };
/** Dark forced on a light phone (the frames' way), the phone's own dark, and light; each at 360 and 414 px. */
const WAYS = [
  { name: 'dark (data-theme)', theme: 'dark', scheme: 'light', attr: 'dark' },
  { name: 'dark (the phone)', theme: 'dark', scheme: 'dark', attr: null },
  { name: 'light', theme: 'light', scheme: 'light', attr: null },
].flatMap((w) => [360, 414].map((width) => ({ ...w, width, name: `${w.name}, ${width} px` })));

const plain = (v) => String(v == null ? '' : v).replace(/⟦[^|⟧]*\|([^⟧]*)⟧/g, '$1').trim();
const is = (n, tag, cls) => Boolean(n && n.tag === tag && (!cls || n.cls.has(cls)));
const bare = (n) => n.cls.size === 0;
const up = (n, pred) => { for (let a = n.parent; a; a = a.parent) if (pred(a)) return a; return null; };
const SANS = /^"IBM Plex Sans"/;
const MONO = /^"IBM Plex Mono"/;

/**
 * AC98's table, by selector, and its kept-small list: each role's match and its look ([size, weight, colour, family]), the
 * colour a token's name. `null` leaves a part unchecked.
 */
const ROLES = [
  // Screen and sheet titles (answer B).
  ['a screen\'s title (.v2-title)', (n) => is(n, 'h1', 'v2-title'), ['28px', '600', 'ink', SANS], { lh: '33.6px' }],
  ['Team\'s, a member\'s and a Details view\'s title (.sb-hdr h1)', (n) => is(n, 'h1') && Boolean(up(n, (a) => a.cls.has('sb-hdr'))), ['28px', '600', 'ink', SANS], { lh: '33.6px' }],
  ['a sheet\'s title (.v2-stitle)', (n) => is(n, 'h2', 'v2-stitle'), ['20px', '600', 'ink', SANS], { lh: '26px' }],
  ['a Team sheet\'s title (.sb-sheet-t)', (n) => n.cls.has('sb-sheet-t'), ['20px', '600', 'ink', SANS], { lh: '26px' }],
  // Section and sheet-block heads, 600 15 px --ink (answer A).
  ['a section head (.v2-shw)', (n) => n.cls.has('v2-shw'), ['15px', '600', 'ink', SANS]],
  ['a section head\'s row (.v2-sh)', (n) => n.cls.has('v2-sh'), ['15px', '600', 'ink', SANS]],
  ['a Plan group head (.v2-plhw)', (n) => n.cls.has('v2-plhw'), ['15px', '600', 'ink', SANS]],
  ['a Home group\'s title (.v2-hgt)', (n) => n.cls.has('v2-hgt'), ['15px', '600', 'ink', SANS]],
  ['"More detail" (.v2-mds)', (n) => n.cls.has('v2-mds'), ['15px', '600', 'ink', SANS]],
  ['Waiting\'s section heads with cards (.v2-kh)', (n) => is(n, 'h2', 'v2-kh'), ['15px', '600', 'ink', SANS]],
  ['a sheet\'s block head (.v2-bh)', (n) => n.cls.has('v2-bh'), ['15px', '600', 'ink', SANS]],
  ['each target\'s name (.v2-vth)', (n) => is(n, 'h3', 'v2-vth'), ['15px', '600', 'ink', SANS]],
  ['a Team or Details head (.sb-h2)', (n) => is(n, 'h2', 'sb-h2'), ['15px', '600', 'ink', SANS]],
  ['a Team sheet\'s head (.sb-sec h3)', (n) => is(n, 'h3') && bare(n) && is(n.parent, 'div', 'sb-sec'), ['15px', '600', 'ink', SANS]],
  // Sub-heads, 600 13 px, each keeping its colour.
  ['a lane\'s head (.v2-lh)', (n) => is(n, 'h2', 'v2-lh'), ['13px', '600', 'ink', SANS]],
  ['a project\'s name heading its group (.v2-gn)', (n) => n.cls.has('v2-gn'), ['13px', '600', 'ink', SANS]],
  ['an opened phase\'s run head (.v2-runh)', (n) => n.cls.has('v2-runh'), ['13px', '600', 'ink', SANS]],
  ['the Timeline\'s goal labels (.v2-goal .v2-label)', (n) => n.cls.has('v2-label') && Boolean(up(n, (a) => a.cls.has('v2-goal'))), ['13px', '600', 'ink2', SANS]],
  ['Plan\'s card label (.v2-plcard > .v2-label)', (n) => n.cls.has('v2-label') && is(n.parent, 'section', 'v2-plcard'), ['13px', '600', 'ink2', SANS]],
  ['"More detail"\'s sub-heads (.sb-h3)', (n) => n.cls.has('sb-h3') && Boolean(up(n, (a) => a.cls.has('v2-home') || a.cls.has('v2-proj'))), ['13px', '600', 'ink', SANS]],
  // An opened phase's two group heads, one step under its run's head.
  ['an opened phase\'s group head (.v2-subh)', (n) => n.cls.has('v2-subh'), ['12px', '600', 'ink', SANS]],
  // An empty section's line, quieter than a full head; " · " and "none" in their mono.
  ['an empty section\'s line (.v2-kq)', (n) => is(n, 'p', 'v2-kq'), ['13px', '500', 'ink2', SANS]],
  ['its words (.v2-kl, .v2-kw)', (n) => (n.cls.has('v2-kl') || n.cls.has('v2-kw')) && is(n.parent, 'p', 'v2-kq'), ['13px', '500', 'ink2', SANS]],
  ['its " · " and "none" (.v2-kn)', (n) => n.cls.has('v2-kn') && is(n.parent, 'p', 'v2-kq'), ['11px', '400', 'ink2', MONO]],
  // The two headings' small part.
  ['" · " and what follows (.v2-shs)', (n) => n.cls.has('v2-shs'), ['12px', '400', 'ink2', SANS]],
  ['the heading\'s time (.v2-shm)', (n) => n.cls.has('v2-shm'), ['12px', '400', 'ink2', MONO]],
  // Beside the heads, each keeping its own look.
  ['a head\'s mono note (.v2-sh .v2-mono)', (n) => n.cls.has('v2-mono') && n.parent && n.parent.cls.has('v2-sh'), ['11px', '400', 'ink2', MONO]],
  ['"Mark as seen" (.v2-seen)', (n) => n.cls.has('v2-seen'), ['11px', '500', 'ink', SANS]],
  ['a lane\'s or section\'s count (.v2-lc)', (n) => n.cls.has('v2-lc'), ['11px', '400', 'ink2', MONO]],
  ['a Home group\'s count (.v2-hgn)', (n) => n.cls.has('v2-hgn'), ['11px', '400', 'ink2', MONO]],
  ['a Home group\'s waiting part (.v2-hgy)', (n) => n.cls.has('v2-hgy'), ['11px', '500', 'ink', SANS]],
  ['"More detail"\'s chevron', (n) => is(n, 'svg') && is(n.parent, 'summary', 'v2-mds'), [null, null, 'ink2', null]],
  // Kept small, on purpose (as drawn, the picture approved, B).
  ['the Timeline\'s pinned band (.v2-tpn)', (n) => n.cls.has('v2-tpn'), ['12px', '600', 'ink', SANS]],
  ['the Timeline\'s compact title (.v2-tn)', (n) => n.cls.has('v2-tn'), ['15px', '600', 'ink', SANS]],
  ['Technical, Context and Why (.v2-bn)', (n) => n.cls.has('v2-bn'), ['11px', '500', 'ink2', SANS]],
  ['a card\'s kind label (.v2-kd)', (n) => n.cls.has('v2-kd'), ['11px', '500', 'ink2', SANS]],
  ['the board\'s buttons (.v2-step)', (n) => n.cls.has('v2-step'), ['11px', '500', null, SANS]],
  ['the folds (.v2-fold)', (n) => n.cls.has('v2-fold') && !n.cls.has('v2-untrb'), ['11px', '500', 'ink2', SANS]],
  ['a field label (.v2-label)', (n) => n.cls.has('v2-label') && !up(n, (a) => a.cls.has('v2-goal')) && !is(n.parent, 'section', 'v2-plcard'), ['11px', '500', 'ink2', SANS]],
  ['a tab (.v2-tab)', (n) => n.cls.has('v2-tab'), ['11px', '500', null, SANS]],
  ['the Now line (.v2-nowl)', (n) => n.cls.has('v2-nowl'), ['11px', '500', 'ink', MONO]],
  ['the small word over Team\'s title (.sb-eyebrow)', (n) => n.cls.has('sb-eyebrow') && Boolean(up(n, (a) => a.cls.has('sb-hdr'))), ['11px', '500', 'ink2', SANS]],
  ['a tile\'s name (.v2-tnm)', (n) => n.cls.has('v2-tnm'), ['13px', '600', null, SANS]],
  ['a phase row\'s name (.v2-sn)', (n) => n.cls.has('v2-sn'), ['13px', '500', null, SANS]],
  ['AC97\'s figure (.v2-vbig)', (n) => n.cls.has('v2-vbig'), ['24px', '600', 'ink', SANS]],
  ['the briefing\'s count (.v2-bt1)', (n) => n.cls.has('v2-bt1') && Boolean(up(n, (a) => a.cls.has('k-you'))), ['18px', '600', null, SANS]],
];
/** The heads that must turn dark: their words in --ink by the token, not a value of their own. */
const DARK_HEADS = ['.v2-shw', '.v2-sh', '.v2-hgt', '.v2-mds', '.v2-kh', '.v2-bh', '.v2-vth'];

/** Each role's look on a screen, in every way; a failure once per role, way and look. */
function check(app, where, fails, met) {
  for (const way of WAYS) {
    const root = document.documentElement;
    const attrs = { ...(root.attrs || {}) };
    if (way.attr) attrs['data-theme'] = way.attr; else delete attrs['data-theme'];
    const tree = cascade(treeOf(app.view, { className: root.className, attrs }), RULES, { scheme: way.scheme, width: way.width, reducedMotion: false });
    const c = INK[way.theme];
    for (const n of nodes(tree)) {
      for (const [name, match, [size, weight, colour, family], extra] of ROLES) {
        if (!match(n)) continue;
        met.add(`${name} · ${way.name}`);
        const got = [plain(n.style.get('font-size')), plain(n.style.get('font-weight')), plain(n.style.get('color')).toLowerCase(), plain(n.style.get('font-family'))];
        const bad = [];
        if (size && got[0] !== size) bad.push(`size ${got[0]}, not ${size}`);
        if (weight && got[1] !== weight) bad.push(`weight ${got[1]}, not ${weight}`);
        if (colour && got[2] !== c[colour]) bad.push(`colour ${got[2]}, not --${colour} ${c[colour]}`);
        if (family && !family.test(got[3])) bad.push(`family ${got[3]}`);
        if (extra && extra.lh && plain(n.style.get('line-height')) !== extra.lh) bad.push(`line height ${plain(n.style.get('line-height'))}, not ${extra.lh}`);
        // The new looks on their grounds: --ink and --ink2 on mockup v2's grounds are 4.5:1 or more (AC88's test measures each).
        if (colour && !GROUND[way.theme].length) bad.push('no ground');
        if (bad.length) {
          const k = `${name} · ${way.name} · ${bad.join(', ')}`;
          if (!fails.some((f) => f.endsWith(k))) fails.push(`${where} · "${String(n.text || '').trim().slice(0, 30)}" · ${k}`);
        }
      }
    }
  }
}

async function opened(setup, hash = '#/', { now = NOW, store = null } = {}) {
  const app = await loadSandbox({ ...setup, hash, now, store });
  await app.advance(1000);
  await app.advance(61_000);
  return app;
}
const hrefsIn = (app, re) => {
  const out = [];
  const walk = (n) => { for (const c of n.children || []) { if (c.tag === 'a' && re.test(c.attrs.href || '') && !out.includes(c.attrs.href)) out.push(c.attrs.href); walk(c); } };
  walk(app.view);
  return out;
};
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Every screen and sheet the fixture reaches, as AC88's walk opens them. */
async function everyScreen(app, projects, where, fails, met, counts) {
  const visit = async (hash) => {
    await app.go('#/');
    await app.go(hash);
    check(app, `${where} ${hash}`, fails, met);
    counts.screens++;
  };
  await visit('#/');
  await visit('#/since');
  for (const r of PF_ROWS) await visit(`#/pf/${r}`);
  await visit('#/waiting');
  for (const h of hrefsIn(app, /^#\/waiting\/card\//)) await visit(h);
  await visit('#/work');
  for (const h of hrefsIn(app, /^#\/work\/ms\//).slice(0, 3)) await visit(h);
  for (const p of projects) {
    const base = `#/p/${encodeURIComponent(p.name)}`;
    await visit(base);
    await visit(`#/waiting/${encodeURIComponent(p.name)}`);
    if (p.model === 'v3') for (const s of ['info', 'values', 'experiments', 'timeline', 'notes']) await visit(`${base}/${s}`);
    else await visit(`${base}/pipeline`);
    for (const s of ['asked', 'agents', 'team']) await visit(`${base}/${s}`);
    await app.go(`${base}/team`);
    if (findAll(app.view, (e) => e.dataset && e.dataset.k === 'team-idle').length) await openIdle(app);
    for (const m of hrefsIn(app, new RegExp(`^${esc(base)}/team/[^/]+$`))) {
      await visit(m);
      for (const s of hrefsIn(app, new RegExp(`^${esc(m)}/(now(/[^/]+)?|e/\\d+)$`)).slice(0, 2)) await visit(s);
    }
  }
}

test('AC98 (the stylesheet): each role\'s rule by selector, in mockup v2\'s block — the titles 600 28 and 600 20 px at the tokens\' line heights, the section heads 600 15 px --ink, the sub-heads 600 13 px, an opened phase\'s group heads 600 12 px, the empty line --t-row --ink2, the small part --t-small --ink2 with its time in Plex Mono 400 12 px; the kept-small rules and every token\'s value unchanged; the older block holds none of them', () => {
  const want = [
    ['.v2-title', /font: 600 28px\/1\.2 var\(--font\)/],
    ['html.sb.v2-page .sb-hdr h1', /font: 600 28px\/1\.2 var\(--font\)/],
    ['.v2-stitle', /font: 600 20px\/1\.3 var\(--font\)/],
    ['html.sb.v2-page .sb-sheet-t', /font: 600 20px\/1\.3 var\(--font\)/],
    ['html.sb.v2-page .sb-h2, html.sb.v2-page .sb-sec h3', /font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/],
    ['.v2-lh', /font: 600 13px\/1\.3 var\(--font\); color: var\(--ink\)/],
    ['.v2-kq', /font: var\(--t-row\); color: var\(--ink2\)/],
    ['.v2-gn', /font: 600 13px\/1\.3 var\(--font\); color: var\(--ink\)/],
    ['.v2-bh', /font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/],
    ['.v2-shw', /font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/],
    ['.v2-shs', /font: var\(--t-small\); color: var\(--ink2\)/],
    ['.v2-shm', /font: 400 12px\/1\.4 var\(--mono\)/],
    ['.v2-mds > .v2-k', /color: var\(--ink2\)/],
    ['html.sb .v2-home .sb-h3', /font: 600 13px\/1\.3 var\(--font\)/],
    ['html.sb .v2-proj .sb-h3', /font: 600 13px\/1\.3 var\(--font\)/],
    ['.v2-runh', /font: 600 13px\/1\.3 var\(--font\); color: var\(--ink\)/],
