    ['.v2-plcard > .v2-label', /font: 600 13px\/1\.3 var\(--font\)/],
    ['.v2-vth', /font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/],
    // Kept small.
    ['.v2-tpn', /font: 600 12px\/1\.3 var\(--font\)/],
    ['.v2-tn', /font: 600 15px\/1\.3 var\(--font\)/],
    ['.v2-bn', /font: var\(--t-label\); color: var\(--ink2\)/],
