    ['.v2-label', /font: var\(--t-label\); color: var\(--ink2\)/],
    ['.v2-tab', /font: var\(--t-label\); color: var\(--ink2\)/],
    ['.v2-nowl', /font: 500 11px\/1\.4 var\(--mono\)/],
    ['.v2-tnm', /font: 600 13px\/1\.3 var\(--font\)/],
    ['.v2-sn', /font: var\(--t-row\)/],
    ['.v2-step.off', /color: var\(--ink2\)/],
    ['.v2-brief.k-you .v2-bt1', /font: var\(--t-sheet\)/],
  ];
  for (const [sel, re] of want) assert.match(rule(sel), re, sel);
  for (const sel of ['.v2-sh', '.v2-kh', '.v2-mds', '.v2-hgt']) assert.match(rule(sel), /font: 600 15px\/1\.3 var\(--font\);[^}]*color: var\(--ink\)|color: var\(--ink\);[^}]*font: 600 15px/, sel);
  assert.ok(/font: 600 15px\/1\.3 var\(--font\); color: var\(--ink\)/.test(rule('.v2-hgt')), '.v2-hgt');
  // Every head turned dark by the token, never a colour of its own.
  for (const sel of DARK_HEADS) assert.match(rule(sel), /color: var\(--ink\)/, `${sel} in --ink by the token`);
  // The folds and the board's buttons unchanged (--t-label).
  assert.equal((V2.match(/\.v2-fold \{[^}]*font: var\(--t-label\)/g) || []).length, 2, 'the folds\' two rules in --t-label');
  assert.match(V2, /\.v2-gatebtns \.v2-step \{[^}]*font: var\(--t-label\)/);
  // The tokens' values unchanged (AC81): AC97's figure 24 px by --t-title and the briefing's count 18 px by --t-sheet.
  const tok = Object.fromEntries([...FLAT.slice(FLAT.indexOf('html.sb .v2, html.sb.v2-page {')).matchAll(/(--t-[a-z]+): ([^;]+);/g)].slice(0, 9).map((m) => [m[1], m[2]]));
  assert.deepEqual(tok, {
    '--t-title': '600 24px/1.2 var(--font)', '--t-sheet': '600 18px/1.3 var(--font)', '--t-lead': '400 15px/1.45 var(--font)',
    '--t-row': '500 13px/1.35 var(--font)', '--t-body': '400 13px/1.45 var(--font)', '--t-small': '400 12px/1.4 var(--font)',
    '--t-label': '500 11px/1.35 var(--font)', '--t-mono': '400 11px/1.4 var(--mono)', '--t-input': '400 16px/1.4 var(--font)',
  });
  assert.match(FLAT, /--t-screen: var\(--t-title\); --t-section: var\(--t-label\);/, 'the older look\'s roles still name the same tokens');
  // Every new rule in mockup v2's block; the older block (AC62's) holds none of the new sizes or classes.
  assert.doesNotMatch(OLDER, /28px|20px|600 15px|v2-shs|v2-shm/, 'the older block unchanged by HD1');
  // AC81's pairs: exactly 600 28 and 600 20 new, and in Plex Mono 400 12; no font-size of its own, no other weight.
  const fonts = [...V2.matchAll(/(?:^|[{;\s])font\s*:\s*(\d{3}) (\d+)px\/[\d.]+(?:px)? var\(--(font|mono)\)/g)].map((m) => `${m[3]} ${m[1]} ${m[2]}`);
  for (const f of ['font 600 28', 'font 600 20', 'mono 400 12']) assert.ok(fonts.includes(f), f);
  assert.doesNotMatch(V2, /font-size\s*:/);
  for (const m of V2.matchAll(/font-weight\s*:\s*([^;}]+)/g)) assert.match(m[1].trim(), /^(400|500|600)$/);
  // The gate sheet's title still held to two lines at its line height.
  assert.match(V2, /\.v2-stitle > \.v2-stt[^{]*\{[^}]*max-height: calc\(2 \* 1\.3em\)|max-height: calc\(2 \* 1\.3em\)/);
});

test('AC98 ("Two headings on one line"): "Since you last looked · <time>" and "Milestones by phase · <count>" split at their first " · " in sandbox.js — the words before it the head\'s, " · " and what follows in `.v2-shs`, a clock time in `.v2-shm` (Plex Mono) and "in the last 7 days" and the count in Plex Sans; the words unchanged and read whole', async () => {
  assert.match(JS, /function splitHead\(words, mono\)/);
  assert.match(JS, /splitHead\(sv\.heading, Boolean\(sv\.time\) && sv\.time !== HOME_WORDS\.lastWeek\)/);
  assert.match(JS, /splitHead\(PAGE_WORDS\.milestonesHead\(mv\.tracked \? mv\.sum : null\), false\)/);
  // Home, "last looked" yesterday, earlier in the week and before that (made up); and markers off (no " · ").
  const DAY = 24 * 3600e3;
  for (const [looked, re, mono] of [[NOW - 20 * 3600e3, /^yesterday, \d\d:\d\d$/, true], [NOW - 3600e3, /^\d\d:\d\d$/, true], [NOW - 4 * DAY, /^\d{1,2} [A-Z][a-z]{2}, \d\d:\d\d$/, true],
    [NOW - 9 * DAY, new RegExp(`^${HOME_WORDS.lastWeek}$`), false]]) {
    const app = await loadSandbox({ ...textSetup(), hash: '#/', now: NOW, store: lookedAt(looked) });
    try {
      await app.advance(1000);
      await app.advance(POLL_MS);
      const h2 = byClass(findAll(app.view, (e) => e.dataset && e.dataset.k === 'since-h')[0], 'v2-shw')[0];
      const [words, small] = h2.children;
      assert.equal(words.textContent, HOME_WORDS.since, 'the head\'s words');
      assert.match(small.className, /\bv2-shs\b/);
      assert.equal(small.children[0].textContent, ' · ');
      const after = small.textContent.slice(3);
      assert.match(after, re);
      assert.equal(byClass(small, 'v2-shm').length, mono ? 1 : 0, `${after}: ${mono ? 'a time, in Plex Mono' : 'words, in Plex Sans'}`);
      assert.equal(h2.textContent, `${HOME_WORDS.since} · ${after}`, 'read whole, unchanged');
      assert.ok(byClass(h2.parentNode, 'v2-seen').length === 1, 'beside "Mark as seen"');
    } finally {
      app.restore();
    }
  }
  // Markers off: the head alone, no small part.
  {
    const app = await opened(textSetup(), '#/', { store: memStore({ 'desk-markers-v1': 'off' }) });
    try {
      const h2 = byClass(findAll(app.view, (e) => e.dataset && e.dataset.k === 'since-h')[0], 'v2-shw')[0];
      if (h2.textContent === HOME_WORDS.since) assert.equal(byClass(h2, 'v2-shs').length, 0);
    } finally {
      app.restore();
    }
  }
  // A project's page: "· <R> of <T> reached" and "· none tracked yet", in Plex Sans, beside "↑ start at the foot".
  const seenForms = new Set();
  for (const setup of [textSetup(), extremes()]) {
    const app = await opened(setup);
    try {
      for (const p of setup.config.projects) {
        await app.go(`#/p/${encodeURIComponent(p.name)}`);
        const head = findAll(app.view, (e) => e.dataset && e.dataset.k === 'ms-h')[0];
        if (!head) continue;
        const h2 = byClass(head, 'v2-shw')[0];
        const small = byClass(h2, 'v2-shs')[0];
        if (!small) { assert.equal(h2.textContent, PAGE_WORDS.milestonesHead(null)); continue; }
        assert.equal(h2.children[0].textContent, 'Milestones by phase');
        assert.match(small.textContent, /^ · (\d+ of \d+ reached|none tracked yet)$/);
        seenForms.add(/none/.test(small.textContent) ? 'none' : 'count');
        assert.equal(byClass(small, 'v2-shm').length, 0, 'the count in Plex Sans');
        assert.equal(byClass(head, 'v2-mono')[0].textContent, PAGE_WORDS.startFoot, 'beside "↑ start at the foot"');
      }
    } finally {
      app.restore();
    }
  }
  assert.ok(seenForms.has('count'), 'a count drawn');
});

test('AC98: every role in AC98\'s table by selector — its computed size, weight and colour — on every screen and sheet from each fixture, in dark (forced, and the phone\'s own) and light, at 360 and 414 px; the counts, the mono notes and "Mark as seen" beside the heads in their own look; the kept-small roles unchanged, each measured', async () => {
  const fails = [];
  const met = new Set();
  const counts = { screens: 0 };
  const walk = async (setup, projects, where, hash = '#/', opts = {}) => {
    const app = await opened(setup, hash, opts);
    try {
      await everyScreen(app, projects, where, fails, met, counts);
    } finally {
      app.restore();
    }
  };
  const t = textSetup();
  await walk(t, t.config.projects, 'text');
  const x = extremes();
  await walk(x, x.config.projects, 'md-extremes');
  await walk({ config: { ...CONFIG, projects: [SD3] }, repos: { 'Service-Desk': sdRepo() } }, [SD3], 'service-desk + J12');
  await walk(waSetup({ extra: { 'intake/estimates.jsonl': WORKED() } }), [], 'plan', '#/work', { now: Date.parse('2026-10-18T18:00:00Z'), store: memStore() });
  // The states the walk does not reach: Home with "Since you last looked"; Waiting with no question and nothing kicked back,
  // and the strip with cards, every project shown and one; a gate's sheet; a project's page with every phase opened.
  const one = async (where, setup, hash, store, then) => {
    const app = await loadSandbox({ ...setup, hash, now: NOW, store });
    try {
      await app.advance(1000);
      await app.advance(POLL_MS);
      if (then) await then(app);
      check(app, where, fails, met);
      counts.screens++;
    } finally {
      app.restore();
    }
  };
  await one('Home, "Since you last looked" yesterday', textSetup(), '#/', lookedAt(NOW - 20 * 3600e3));
  await one('Waiting, quiet', quietState(), '#/waiting', memStore());
  await one('Waiting, kicked back, every project', twoMixState(), '#/waiting', memStore(deviceMarks(KICKED)));
  await one('Waiting, kicked back, one project', twoMixState(), `#/waiting/${MIX_PROJECT}`, memStore(deviceMarks(KICKED)));
  await one('a gate\'s sheet', gatesState(), `#/waiting/card/${encodeURIComponent(GATE_KEY(MIX_PROJECT, GATE4))}`, memStore());
  await one('a page, every phase opened', textState(), `#/p/${SD.name}`, memStore(), async (app) => {
    for (const ph of ['Launch', 'Build', 'Design', 'Discovery']) await app.tap(findAll(app.view, (e) => e.tag === 'button' && e.attrs && e.attrs['aria-label'] === ph)[0]);
  });
  for (const [where, open] of [...G9_OPENS, ...QW1_OPENS, ...VT1_OPENS]) {
    const app = await open();
    try {
      check(app, where, fails, met);
      counts.screens++;
    } finally {
      app.restore();
    }
  }
  assert.ok(counts.screens > 250, `${counts.screens} screens and sheets`);
  assert.deepEqual(fails, []);
  // Each role was measured, in every way.
  const missing = ROLES.flatMap(([name]) => WAYS.map((w) => `${name} · ${w.name}`)).filter((k) => !met.has(k));
  assert.deepEqual(missing, [], 'every role drawn and measured in every way');
});

